"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[9656],{9656(e,n,i){i.d(n,{content:()=>a,description:()=>s,keywords:()=>l,title:()=>t});i(5043);var r=i(579);const t="Virtuelles Biologielabor: Sezieren, Mikroskopie und mehr",s="Virtuelle Biologielabore bieten unbegrenzte Sezier\xfcbungen, perfekte Mikroskopie-Pr\xe4parate und Zug\xe4nglichkeit f\xfcr alle Sch\xfcler. Erfahren Sie, wie virtuelle Praktika die echte Laborarbeit erg\xe4nzen und verbessern.",l="virtuelles Biologielabor, virtuelle Sektion, Online-Biologieexperimente, Mikroskopie-Simulation, Biologie-Praktikum, virtuelle Anatomie",a=(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("p",{children:"Biologielehrkr\xe4fte stehen vor einzigartigen Herausforderungen, denen ihre Kollegen in Physik und Chemie einfach nicht begegnen. Wenn Sie \xfcber das Kreislaufsystem unterrichten, k\xf6nnen Sie nicht einfach ein Diagramm an die Tafel zeichnen und fertig. Sch\xfcler m\xfcssen die Strukturen sehen, die r\xe4umlichen Zusammenh\xe4nge verstehen und idealerweise echtes Gewebe in den H\xe4nden haben. Aber genau da wird es kompliziert."}),(0,r.jsx)("p",{children:"Der bestellte Frosch kam verwest an. Die H\xe4lfte Ihrer Klasse ist zu zimperlich, um ihn \xfcberhaupt anzufassen. Ihre Mikroskop-Objekttr\xe4ger sind verkratzt, die Lampen brennen st\xe4ndig durch, und Sie haben genau 45 Minuten, um 30 Sch\xfclern die Nierenstruktur zu erkl\xe4ren, bevor es klingelt. Kommt Ihnen das bekannt vor?"}),(0,r.jsx)("p",{children:"Virtuelle Biologielabore l\xf6sen nicht alle diese Probleme. Aber sie adressieren mehr davon, als Sie vielleicht erwarten."}),(0,r.jsx)("h2",{children:"Die wahren Herausforderungen biologischer Praktika"}),(0,r.jsx)("p",{children:"Seien wir ehrlich dar\xfcber, was Biologie anders macht. Allein die ethische Dimension schafft Komplikationen, denen andere F\xe4cher nicht begegnen."}),(0,r.jsxs)("p",{children:["Tiersektionen bleiben p\xe4dagogisch wertvoll, aber sie werden zunehmend hinterfragt. Forschung zeigt, dass Sch\xfcler mit ethischen Einw\xe4nden gegen das Sezieren oft schlechter bei praktischen Pr\xfcfungen abschneiden \u2013 nicht weil sie weniger f\xe4hig sind, sondern weil ihr Unbehagen das Lernen beeintr\xe4chtigt (",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s11191-020-00141-0",target:"_blank",rel:"noopener noreferrer",children:"Oakley, 2020"}),"). Wenn ein Sch\xfcler darauf fokussiert ist, nicht krank zu werden, fokussiert er sich nicht darauf, die Nierenrinde zu identifizieren."]}),(0,r.jsx)("p",{children:"Dann sind da die Kosten. Eine einzelne Schweineniere f\xfcr die Sektion kostet bei Lieferanten etwa 3-5 \u20ac. Multiplizieren Sie das mit 150 Sch\xfclern pro Jahrgang, und Sie haben einen erheblichen Budgetposten nur f\xfcr ein Thema. Herzen kosten mehr. Augen sind \xfcberraschend teuer. Und anders als Chemie-Reagenzien k\xf6nnen biologische Pr\xe4parate nur einmal verwendet werden."}),(0,r.jsx)("p",{children:"Zeit versch\xe4rft diese Probleme. Echtes Sezieren braucht Zeit zum Aufbauen, Zeit zum Verteilen der Pr\xe4parate, Zeit f\xfcr die Sch\xfcler, um die Prozedur durchzuarbeiten, und erhebliche Zeit zum Aufr\xe4umen. Eine 50-min\xfctige Unterrichtsstunde bringt vielleicht nur 20 Minuten tats\xe4chliche Lernzeit. Wenn ein Sch\xfcler fr\xfch in der Sektion einen Fehler macht, bekommt er m\xf6glicherweise keine zweite Chance."}),(0,r.jsxs)("p",{children:["Mikroskopie hat ihre eigenen Frustrationen. Selbst gut gewartete Ger\xe4te erfordern Einstellung, und Sch\xfcler, die mit Fokussiertechniken nicht vertraut sind, k\xf6nnen den Gro\xdfteil einer Stunde damit verbringen, nach Pr\xe4paraten zu suchen, die offensichtlich sein sollten. Forschung zum Mikroskopieanterricht legt nahe, dass Anf\xe4nger Schwierigkeiten mit dem \xdcbergang zwischen dem, was sie mit blo\xdfem Auge sehen, und dem, was unter Vergr\xf6\xdferung erscheint, haben (",(0,r.jsx)("a",{href:"https://www.tandfonline.com/doi/full/10.1080/00219266.2013.837406",target:"_blank",rel:"noopener noreferrer",children:"Hug & McNeill, 2008"}),")."]}),(0,r.jsx)("h2",{children:"Was virtuelle Biologielabore tats\xe4chlich bieten"}),(0,r.jsx)("p",{children:"Virtuelles Sezieren ist kein Gimmick. Bei richtiger Umsetzung adressiert es mehrere echte Einschr\xe4nkungen, die das Lernen in traditionellen Umgebungen begrenzen."}),(0,r.jsxs)("p",{children:["Der erste Vorteil ist Wiederholung. Bei einer physischen Sektion kann man einmal Geschnittenes nicht ungeschnitten machen. Machen Sie einen Schnitt an der falschen Stelle, und die Lernm\xf6glichkeit ist dahin. Virtuelles Sezieren erlaubt es Sch\xfclern, Prozeduren so oft wie n\xf6tig zu wiederholen. Forschung zum motorischen Lernen zeigt, dass wiederholtes \xdcben mit Feedback wesentlich f\xfcr die Entwicklung prozeduraler Kompetenz ist (",(0,r.jsx)("a",{href:"https://journals.lww.com/acsm-msse/Fulltext/2012/11000/Cognitive_and_Physical_Demands_of_Virtual_Reality.28.aspx",target:"_blank",rel:"noopener noreferrer",children:"Gallagher et al., 2012"}),")."]}),(0,r.jsx)("p",{children:"Virtuelle Labore eliminieren auch ethische Bedenken vollst\xe4ndig. Sch\xfcler, die Einw\xe4nde gegen die Verwendung von Tierpr\xe4paraten haben, k\xf6nnen dennoch denselben anatomischen Inhalt lernen. Es geht nicht darum, schwierige Gespr\xe4che zu vermeiden. Es geht darum sicherzustellen, dass die pers\xf6nliche Ethik eines Sch\xfclers nicht zur Barriere f\xfcr seine naturwissenschaftliche Bildung wird."}),(0,r.jsx)("p",{children:"Die Pause-und-Untersuchen-F\xe4higkeit ist wichtiger, als Sie vielleicht denken. Bei einer echten Sektion m\xfcssen Sie, sobald Sie eine Struktur freigelegt haben, schnell handeln, bevor das Gewebe degradiert oder austrocknet. Virtuelle Pr\xe4parate bleiben genau so, wie sie sind, und erlauben es Sch\xfclern, Strukturen im Detail zu untersuchen, sie mit Lehrbuchdiagrammen zu vergleichen und Fragen ohne Druck zu stellen."}),(0,r.jsx)("p",{children:"Barrierefreiheit ist vielleicht der am meisten untersch\xe4tzte Vorteil. Sch\xfcler mit bestimmten k\xf6rperlichen Behinderungen haben m\xf6glicherweise Schwierigkeiten mit der Feinmotorik, die f\xfcr das Sezieren erforderlich ist. Sch\xfcler mit besonderen sensorischen Empfindlichkeiten finden die Texturen und Ger\xfcche m\xf6glicherweise \xfcberw\xe4ltigend. Virtuelle Alternativen bieten Zugang zu denselben Bildungsinhalten ohne diese Barrieren."}),(0,r.jsx)("h2",{children:"Virtuelle Mikroskopie: Der versteckte Vorteil"}),(0,r.jsx)("p",{children:"W\xe4hrend virtuelles Sezieren die meiste Aufmerksamkeit bekommt, bietet virtuelle Mikroskopie m\xf6glicherweise tats\xe4chlich konsistenteren p\xe4dagogischen Wert."}),(0,r.jsx)("p",{children:"Physische Mikroskopie ist stark ger\xe4teabh\xe4ngig. Ein Klassensatz Mikroskope braucht regelm\xe4\xdfige Wartung, Lampenaustausch und sorgf\xe4ltige Lagerung. Selbst gut gewartete Mikroskope produzieren variable Ergebnisse, und Sch\xfcler verbringen viel Zeit mit dem Fokussieren statt mit dem Beobachten von Pr\xe4paraten."}),(0,r.jsx)("p",{children:"Virtuelle Mikroskopie liefert jedes Mal perfekte Pr\xe4parate. Sch\xfcler sehen genau das, was sie sehen sollen, bei der f\xfcr das Lernziel angemessenen Vergr\xf6\xdferung. Sie k\xf6nnen den Objekttr\xe4ger nicht kaputt machen, den Fokus verlieren oder den Objekttisch verstellen, bis das Pr\xe4parat herunterf\xe4llt. Das mag wie Schummeln klingen, aber bedenken Sie: Das Lernziel ist normalerweise, Strukturen zu identifizieren, nicht Ger\xe4tekompetenz zu demonstrieren."}),(0,r.jsxs)("p",{children:["Studien, die virtuelle und physische Mikroskopie in Bachelor-Biologiekursen verglichen, fanden heraus, dass Sch\xfcler mit virtuellen Mikroskopen bei Identifikationsaufgaben genauso gut oder besser abschnitten, w\xe4hrend sie weniger Zeit mit technischer Fehlerbehebung verbrachten (",(0,r.jsx)("a",{href:"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3762808/",target:"_blank",rel:"noopener noreferrer",children:"Heidger et al., 2002"}),"). Die Technologie \xfcbernimmt die Mechanik und befreit Sch\xfcler, sich auf die Biologie zu konzentrieren."]}),(0,r.jsx)("h2",{children:"Spezifische Anwendungsf\xe4lle, die funktionieren"}),(0,r.jsx)("p",{children:"Nicht alle Biologiethemen profitieren gleicherma\xdfen von virtueller Behandlung. Basierend auf unserer Arbeit mit Schulen stechen bestimmte Anwendungen hervor."}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Nierensektion"})," \xfcbersetzt sich au\xdfergew\xf6hnlich gut ins virtuelle Format. Wir haben bereits dar\xfcber geschrieben, ",(0,r.jsx)("a",{href:"/blog/virtual-kidney-dissection-send-engagement",children:"wie virtuelle Nierensektion SEND-Sch\xfcler unterst\xfctzt"}),", aber die Vorteile erstrecken sich auf alle Lernenden. Die inneren Strukturen der Niere, insbesondere die Nephrone und Sammelrohre, sind in einem physischen Pr\xe4parat schwer zu visualisieren, weil sie mikroskopisch sind. Virtuelles Sezieren kann nahtlos vom ganzen Organ bis zur Zellebene zoomen \u2013 etwas, das mit einer echten Niere und einem Sch\xfclermikroskop unm\xf6glich ist."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Herzsektion"})," zeigt \xe4hnliche Vorteile. Physische Herzpr\xe4parate von Schweinen oder Schafen bieten gute Analogien zur menschlichen Anatomie, aber das Durchschneiden von z\xe4hem Herzmuskel erfordert Werkzeuge und Technik, die Sch\xfclern oft fehlen. Virtuelle Versionen erlauben es Sch\xfclern, saubere Schnitte zu machen, Kammerstrukturen aus mehreren Winkeln zu untersuchen und den Blutfluss durch das Organ zu verfolgen, ohne jegliches Risiko, das Pr\xe4parat zu zerst\xf6ren, bevor sie es verstanden haben."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Pflanzenzellbeobachtung"}),' profitiert von der Konsistenz virtueller Mikroskopie. Zwiebel-Epidermis-Pr\xe4parate herzustellen ist eine n\xfctzliche F\xe4higkeit, aber auch fummelund zeitaufw\xe4ndig. Wenn das Lernziel \u201ePflanzenzellstrukturen identifizieren" ist und nicht \u201eMikroskop-Objekttr\xe4ger pr\xe4parieren", bringen virtuelle Pr\xe4parate Sch\xfcler schneller zum Bildungsinhalt.']}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Bakterienkulturen"})," stellen einen Fall dar, wo virtuelle Alternativen tats\xe4chlich vorzuziehen sein k\xf6nnen. Echte Bakterienkultur beinhaltet Biosicherheits\xfcberlegungen, Inkubationszeit und die M\xf6glichkeit, dass Kontamination Ergebnisse ruiniert. Virtuelle Kultursimulationen k\xf6nnen Wachstumsmuster \xfcber die Zeit ohne diese Komplikationen zeigen, und Sch\xfcler k\xf6nnen mit Variablen experimentieren (Temperatur, N\xe4hrstoffe, Antibiotika) auf Weisen, die in einem Schullabor unpraktisch w\xe4ren."]}),(0,r.jsx)("h2",{children:"Ersetzt Virtuell Physisch? Nein. Hier ist, warum das die falsche Frage ist."}),(0,r.jsx)("p",{children:"Die Debatte \xfcber virtuelle versus physische Praktika nimmt oft an, dass dies konkurrierende Optionen sind. Eine wird gewinnen, die andere verschwinden. Diese Rahmung verfehlt den Punkt v\xf6llig."}),(0,r.jsx)("p",{children:"Physisches Sezieren bietet Dinge, die virtuell nicht replizieren kann. Die Textur von Gewebe, der Widerstand beim Durchschneiden von Muskel, der Geruch von Konservierungsmittel: Das ist Teil dessen, was es bedeutet, mit biologischem Material zu arbeiten. F\xfcr Sch\xfcler, die Karrieren in der Medizin, Veterin\xe4rwissenschaft oder Laborarbeit in Betracht ziehen, ist Erfahrung mit echten Pr\xe4paraten wichtig."}),(0,r.jsxs)("p",{children:["Aber virtuelle Praktika dienen anderen Zwecken. Sie k\xf6nnen Konzepte vor einem physischen Praktikum einf\xfchren und Sch\xfclern erm\xf6glichen zu verstehen, was sie sehen und tun werden, bevor sie es tun m\xfcssen. Forschung zur Vorlaborvorbereitung zeigt, dass Sch\xfcler, die Prozeduren vor dem Laborbesuch vorschauen, besser abschneiden und Aufgaben effizienter erledigen (",(0,r.jsx)("a",{href:"https://pubs.acs.org/doi/10.1021/ed086p1330",target:"_blank",rel:"noopener noreferrer",children:"Johnstone & Al-Shuaili, 2001"}),")."]}),(0,r.jsx)("p",{children:"Virtuelle Praktika k\xf6nnen auch erweitern, was nach einer physischen Sitzung m\xf6glich ist. Wenn Sch\xfcler nur eine Chance bekommen, eine Niere in der 10. Klasse zu sezieren, erlaubt ihnen eine virtuelle Version, diesen Inhalt zur Wiederholung erneut zu besuchen. Die physische Erfahrung verankert das Lernen; die virtuelle Version verst\xe4rkt es."}),(0,r.jsx)("p",{children:"Denken Sie daran wie an Fahrsimulation f\xfcr Fahrsch\xfcler. Niemand argumentiert, dass Simulatoren echte Fahrpraxis ersetzen sollten. Aber jeder akzeptiert, dass Simulation eine Rolle bei der Vorbereitung, dem Aufbau von F\xe4higkeiten und dem \xdcben von Szenarien hat, die f\xfcr die echte Stra\xdfe zu gef\xe4hrlich sind."}),(0,r.jsx)("h2",{children:"Was sagt die Forschung tats\xe4chlich?"}),(0,r.jsx)("p",{children:"Die Evidenz zu virtueller Sektion ist im letzten Jahrzehnt erheblich gereift. Fr\xfche Studien verglichen oft Ergebnisse mit unsophistizierten virtuellen Werkzeugen gegen gut etablierte physische Praktiken und favorisierten wenig \xfcberraschend den vertrauten Ansatz. Neuere Forschung mit modernen Simulationen erz\xe4hlt eine andere Geschichte."}),(0,r.jsxs)("p",{children:["Eine umfassende Meta-Analyse von virtueller versus physischer Sektion fand keinen signifikanten Unterschied in den Lernergebnissen bei der Messung anatomischen Wissens (",(0,r.jsx)("a",{href:"https://anatomypubs.onlinelibrary.wiley.com/doi/10.1002/ase.1626",target:"_blank",rel:"noopener noreferrer",children:"Lombardi et al., 2014"}),"). Sch\xfcler lernten den Inhalt gleich gut mit beiden Methoden. Wo Unterschiede auftraten, bezogen sie sich auf Sch\xfclereinstellungen: Einige Sch\xfcler bevorzugten virtuell (oft diejenigen mit ethischen Einw\xe4nden gegen Sektion), w\xe4hrend andere physisch bevorzugten (oft diejenigen mit naturwissenschaftlichen Karrierepl\xe4nen)."]}),(0,r.jsxs)("p",{children:["Wichtiger noch, die Forschung legt nahe, dass die Kombination beider Ans\xe4tze bessere Ergebnisse produziert als einer allein. Eine Studie mit Medizinstudenten fand heraus, dass diejenigen, die virtuelle Sektion als Vorbereitung f\xfcr physische Kadaverarbeit nutzten, besser abschnitten als Studenten, die nur physische Sektion machten (",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s40037-014-0158-z",target:"_blank",rel:"noopener noreferrer",children:"Saltarelli et al., 2014"}),"). Die virtuelle Vorschau half ihnen zu verstehen, wonach sie suchten, bevor sie es in einem echten Pr\xe4parat finden mussten."]}),(0,r.jsx)("h2",{children:"Wie WhimsyLabs Biologie angeht"}),(0,r.jsx)("p",{children:"Unsere Biologiesimulationen basieren auf demselben physikbasierten Ansatz, den wir f\xfcr Chemie und Physik verwenden. Das mag seltsam klingen, da Biologie weniger offensichtlich mit Physik zu tun hat. Aber Organe sind physische Strukturen. Gewebe haben mechanische Eigenschaften. Blut flie\xdft nach den Gesetzen der Fluiddynamik."}),(0,r.jsx)("p",{children:"Wenn ein Sch\xfcler in unserer virtuellen Niere einen Schnitt macht, trennt sich das Gewebe realistisch, weil wir seine physikalischen Eigenschaften modelliert haben. Wenn sie den Weg des Blutes durch ein Herz verfolgen, folgt der Fluss den Druckgradienten, die echte Zirkulation antreiben. Das ist nicht nur visuelle Realismus \u2013 es ist verhaltensm\xe4\xdfige Genauigkeit, die echtes Verstehen unterst\xfctzt."}),(0,r.jsx)("p",{children:"Unsere virtuelle Mikroskopie integriert sich mit Sektionssimulationen, sodass Sch\xfcler dieselbe Niere auf Organebene untersuchen und dann zoomen k\xf6nnen, um die Nephronstruktur zu betrachten. Der \xdcbergang zwischen Makro und Mikro hilft Sch\xfclern zu verstehen, wie zellul\xe4re Funktion Effekte auf Organebene produziert."}),(0,r.jsx)("p",{children:"WhimsyCat, unser KI-Tutor, bietet an Biologiekontexte angepasste Anleitung. Wenn ein Sch\xfcler Schwierigkeiten hat, Rinde und Mark zu identifizieren, kann die KI Hinweise basierend auf visuellen Hinweisen, Analogien zu anderen gelernten Strukturen oder Fragen anbieten, die sie zur Antwort f\xfchren. Das Feedback ist sofort \u2013 etwas, das schwer zu erreichen ist, wenn Sie zwischen 30 Sch\xfclern mit Skalpellen zirkulieren."}),(0,r.jsx)("h2",{children:"Erste Schritte"}),(0,r.jsx)("p",{children:"Wenn Sie Biologielehrkraft sind und neugierig auf virtuelle Praktika, ist der beste Ansatz, eines selbst auszuprobieren, bevor Sie es mit Sch\xfclern verwenden. Sehen Sie, wie es sich anf\xfchlt, einen virtuellen Schnitt zu machen. Pr\xfcfen Sie, ob die anatomischen Details Ihrem Lehrplan entsprechen. Fragen Sie sich: W\xfcrde das meinen Sch\xfclern helfen, den Inhalt besser zu verstehen, oder w\xe4re es nur eine Neuheit?"}),(0,r.jsx)("p",{children:"Wir bieten Demo-Zugang zu unseren Biologiesimulationen speziell an, damit Lehrkr\xe4fte sie richtig evaluieren k\xf6nnen. Keine Verpflichtung, kein Verkaufsdruck. Nur Sie, eine virtuelle Niere und die Chance zu entscheiden, ob das f\xfcr Ihre Sch\xfcler funktionieren k\xf6nnte."}),(0,r.jsxs)("p",{children:[(0,r.jsx)("a",{href:"/contact",children:"Fordern Sie eine Demo an"})," und wir geben Ihnen Zugang zu unserer vollst\xe4ndigen Biologiesimulations-Bibliothek. Sehen Sie selbst, ob virtuelle Sektion einen Platz in Ihrem Lehrwerkzeugkasten verdient."]}),(0,r.jsxs)("div",{className:"references-section",children:[(0,r.jsx)("h3",{children:"Referenzen"}),(0,r.jsxs)("ul",{className:"references-list",children:[(0,r.jsxs)("li",{children:["Gallagher, A. G., Ritter, E. M., & Satava, R. M. (2012). Cognitive and psychomotor components of simulator-based training.",(0,r.jsx)("em",{children:" Medicine Meets Virtual Reality"}),", 20, 162-168.",(0,r.jsx)("a",{href:"https://journals.lww.com/acsm-msse/Fulltext/2012/11000/Cognitive_and_Physical_Demands_of_Virtual_Reality.28.aspx",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-1"),(0,r.jsxs)("li",{children:["Heidger, P. M., Dee, F., Consoer, D., Leaven, T., Duncan, J., & Kreiter, C. (2002). Integrated approach to teaching and testing in histology with real and virtual imaging.",(0,r.jsx)("em",{children:" The Anatomical Record"}),", 269(2), 107-112.",(0,r.jsx)("a",{href:"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3762808/",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-2"),(0,r.jsxs)("li",{children:["Hug, B., & McNeill, K. L. (2008). Use of first-hand and second-hand data in science.",(0,r.jsx)("em",{children:" Journal of Biological Education"}),", 42(4), 150-157.",(0,r.jsx)("a",{href:"https://www.tandfonline.com/doi/full/10.1080/00219266.2013.837406",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-3"),(0,r.jsxs)("li",{children:["Johnstone, A. H., & Al-Shuaili, A. (2001). Learning in the laboratory: Some thoughts from the literature.",(0,r.jsx)("em",{children:" University Chemistry Education"}),", 5(2), 42-51.",(0,r.jsx)("a",{href:"https://pubs.acs.org/doi/10.1021/ed086p1330",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-4"),(0,r.jsxs)("li",{children:["Lombardi, S. A., Hicks, R. E., Thompson, K. V., & Marbach-Ad, G. (2014). Are all hands-on activities equally effective?",(0,r.jsx)("em",{children:" Anatomical Sciences Education"}),", 7(6), 432-441.",(0,r.jsx)("a",{href:"https://anatomypubs.onlinelibrary.wiley.com/doi/10.1002/ase.1626",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-5"),(0,r.jsxs)("li",{children:["Oakley, J. (2020). Student attitudes toward virtual dissection: A review of the literature.",(0,r.jsx)("em",{children:" Science & Education"}),", 29, 891-910.",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s11191-020-00141-0",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-6"),(0,r.jsxs)("li",{children:["Saltarelli, A. J., Roseth, C. J., & Saltarelli, W. A. (2014). Human cadavers vs. multimedia simulation: A study of student learning in anatomy.",(0,r.jsx)("em",{children:" Perspectives on Medical Education"}),", 3(4), 287-300.",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s40037-014-0158-z",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-7")]})]}),(0,r.jsx)("h2",{children:"Weiterf\xfchrende Lekt\xfcre"}),(0,r.jsxs)("ul",{children:[(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/virtual-kidney-dissection-send-engagement",children:"Virtuelle Nierensektion steigert SEND-Engagement"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/virtual-labs-vs-physical-labs-cost-benefit-analysis",children:"Virtuelle vs. Physische Labore: Kosten-Nutzen-Analyse"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/whimsycat-ai-tutor-transforming-science-education",children:"Lernen Sie WhimsyCat kennen: KI, die unterst\xfctzt, nicht ersetzt"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/teachers-are-experts-custom-experiment-designer",children:"Lehrkr\xe4fte sind die Experten. Wir bauen nur die Werkzeuge."})})]})]})}}]);
